#[cfg(test)]
mod tests {
    use chrono::{TimeZone, Utc};
    use rigorix_engine::effect_commitment::domain::{EffectState, ObservedOutcome, OutcomeVerdict};

    fn at() -> chrono::DateTime<Utc> {
        Utc.with_ymd_and_hms(2026, 10, 20, 12, 0, 0).unwrap()
    }

    #[test]
    fn test_observedoutcome_is_defined() {
        let success = ObservedOutcome::committed("receipt-1", "readback-1", at(), "stripe");
        assert!(success.is_committed());
        assert_eq!(success.verdict, OutcomeVerdict::Committed);
        assert_eq!(success.terminal_state(), EffectState::Committed);
        assert_eq!(success.receipt_id, "receipt-1");

        let failure = ObservedOutcome::not_committed("receipt-2", "readback-2", at(), "stripe");
        assert!(!failure.is_committed());
        assert_eq!(failure.terminal_state(), EffectState::NotCommitted);
    }

    #[test]
    fn test_observedoutcome_interacts_with_none() {
        // Evidence is the only thing that may settle an effect, so it must be
        // serializable for the signed record and the HTTP contract.
        let outcome = ObservedOutcome::committed("receipt-1", "readback-1", at(), "stripe");
        let json = serde_json::to_string(&outcome).unwrap();
        assert!(json.contains("\"verdict\":\"committed\""));
        let round_trip: ObservedOutcome = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, outcome);

        // The verdict maps onto exactly the two terminal commitment states.
        assert_eq!(
            OutcomeVerdict::Committed.terminal_state(),
            EffectState::Committed
        );
        assert_eq!(
            OutcomeVerdict::NotCommitted.terminal_state(),
            EffectState::NotCommitted
        );
    }
}
